components.css:
.ds-form-box { background: var(--bone); color: var(--ink); border: 1.5px solid var(--ink); padding: 26px 22px 22px; position: relative; font: 400 14px/1.55 "Archivo", "Segoe UI", system-ui, sans-serif; }
.ds-form-box__label { position: absolute; top: -1px; left: -1px; background: var(--ink); color: var(--bone); margin: 0; padding: 5px 11px 4px; font: 700 14px/1.2 "Archivo", "Segoe UI", system-ui, sans-serif; letter-spacing: .04em; text-transform: uppercase; }
.ds-form-box__lead { color: var(--ink-70); margin: 10px 0 16px; }
.ds-form-box__body { font-family: "Courier Prime", "Courier New", Consolas, monospace; font-variant-numeric: tabular-nums; font-size: 13px; }

.ds-btn { border: 1.5px solid var(--ink); background: var(--bone); color: var(--ink); padding: 9px 13px; cursor: pointer; font: 700 11px/1.4 "Archivo", "Segoe UI", system-ui, sans-serif; letter-spacing: .1em; text-transform: uppercase; }
.ds-btn:hover:not(:disabled) { background: var(--pink); }
.ds-btn:focus-visible { outline: 2px solid var(--pen); outline-offset: 2px; }
.ds-btn:disabled { opacity: .45; cursor: default; }

.ds-btn-primary { border: 1.5px solid var(--ink); background: var(--ink); color: var(--bone); padding: 9px 13px; cursor: pointer; font: 700 11px/1.4 "Archivo", "Segoe UI", system-ui, sans-serif; letter-spacing: .1em; text-transform: uppercase; }
.ds-btn-primary:hover:not(:disabled) { background: var(--ink); color: var(--green); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--pen); outline-offset: 2px; }
.ds-btn-primary:disabled { opacity: .45; cursor: default; }

.ds-chip { display: inline-block; font: 700 11px/1.2 "Archivo", "Segoe UI", system-ui, sans-serif; letter-spacing: .12em; text-transform: uppercase; padding: 5px 10px 4px; border: 1.5px solid var(--ink); color: var(--ink); background: var(--bone); white-space: nowrap; }
.ds-chip--ok { background: var(--green); }
.ds-chip--warn { background: var(--pink); border-color: var(--stamp); color: var(--stamp-ink); }
.ds-chip--ai { background: var(--bone); border-color: var(--pen); color: var(--pen); }

.ds-stub { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; padding: 13px 20px 13px 18px; cursor: pointer; border-top: 1px solid var(--ink-12); background: var(--bone); }
.ds-stub:hover { background: var(--pink); }
.ds-stub--selected { background: var(--pink); border-top: 2px solid var(--ink); border-bottom: 2px solid var(--ink); padding-left: 15px; }
.ds-stub__title { margin: 0 0 3px; font: 700 11px/1.3 "Archivo", "Segoe UI", system-ui, sans-serif; letter-spacing: .12em; text-transform: uppercase; color: var(--ink); }
.ds-stub__meta { margin: 1px 0; font: 400 12px/1.4 "Courier Prime", "Courier New", Consolas, monospace; color: var(--ink-70); }
.ds-stub__state { font: 700 11px/1.2 "Archivo", "Segoe UI", system-ui, sans-serif; letter-spacing: .12em; text-transform: uppercase; border: 1px solid var(--ink-45); padding: 3px 7px 2px; white-space: nowrap; align-self: start; }
.ds-stub__state--review { border-color: var(--stamp); color: var(--stamp-ink); background: var(--pink); }

.ds-xbox { width: 18px; height: 18px; border: 1.5px solid var(--ink); display: inline-flex; align-items: center; justify-content: center; font: 700 12px/1 "Courier Prime", "Courier New", Consolas, monospace; color: var(--ink); background: var(--bone); }
.ds-xbox--ok { background: var(--green); }
.ds-xbox--void { border-color: var(--stamp); color: var(--stamp-ink); background: var(--pink); text-decoration: line-through; }

.ds-impressions { display: flex; gap: 8px; flex-wrap: wrap; }
.ds-imp { border: 1.5px solid var(--ink-45); padding: 3px 8px 2px; font: 400 11px/1.5 "Courier Prime", "Courier New", Consolas, monospace; letter-spacing: .06em; color: var(--ink); background: var(--bone); }
.ds-imp--stamped { border-color: var(--ink); background: var(--green); }
.ds-imp--void { border-color: var(--stamp); color: var(--stamp-ink); background: var(--pink); }
.ds-impressions--press .ds-imp--stamped, .ds-impressions--press .ds-imp--void { animation: ds-stamp-press .32s cubic-bezier(.19, 1, .22, 1); }
@keyframes ds-stamp-press { from { transform: rotate(-4deg) scale(1.18); opacity: 0; } 60% { opacity: 1; } to { transform: rotate(-4deg) scale(1); opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .ds-impressions--press .ds-imp--stamped, .ds-impressions--press .ds-imp--void { animation: none; } }

.ds-void-stamp { display: inline-flex; align-items: center; border: 3px double var(--stamp); color: var(--stamp-ink); padding: 6px 14px 5px; transform: rotate(-4deg); font: 700 13px/1.2 "Archivo", "Segoe UI", system-ui, sans-serif; letter-spacing: .18em; text-transform: uppercase; background: var(--bone); animation: ds-stamp-press .32s cubic-bezier(.19, 1, .22, 1); }
@keyframes ds-stamp-press { from { transform: rotate(-4deg) scale(1.18); opacity: 0; } 60% { opacity: 1; } to { transform: rotate(-4deg) scale(1); opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .ds-void-stamp { animation: none; } }

.ds-sign-block { margin: 16px 0 4px; }
.ds-sign-label { display: block; font: 700 11px/1.3 "Archivo", "Segoe UI", system-ui, sans-serif; letter-spacing: .14em; text-transform: uppercase; color: var(--pen); }
.ds-sign-line { border-bottom: 1.5px solid var(--pen); width: 240px; height: 26px; margin-top: 6px; }
